static int DrawLevelOvr2P_MempackContains(const struct Mempack *pack, uintptr_t ptr, uintptr_t *span)
{
	uintptr_t start = (uintptr_t)pack->start;
	if ((start == 0) || (pack->packSize <= 0))
	{
		return 0;
	}

	uintptr_t end = start + (uintptr_t)pack->packSize;

	if ((end < start) || (ptr < start) || (ptr >= end))
	{
		return 0;
	}

	if (span != NULL)
	{
		*span = end - start;
	}

	return 1;
}

static const struct Mempack *DrawLevelOvr2P_FindMempackContaining(uintptr_t ptr)
{
	const struct Mempack *bestPack = NULL;
	uintptr_t bestSpan = UINTPTR_MAX;
	struct GameTracker *gGT = sdata->gGT;

	// PtrMempack can point at inactive mask/podium loads while level1 renders.
	if ((gGT == NULL) || ((gGT->gameMode2 & LEV_SWAP) == 0))
	{
		const struct Mempack *mainPack = &sdata->mempack[0];

		return DrawLevelOvr2P_MempackContains(mainPack, ptr, NULL) ? mainPack : NULL;
	}

	for (s32 packIndex = 0; packIndex < 4; packIndex++)
	{
		const struct Mempack *pack = &sdata->mempack[packIndex];
		uintptr_t span;

		if (DrawLevelOvr2P_MempackContains(pack, ptr, &span))
		{
			if (span < bestSpan)
			{
				bestPack = pack;
				bestSpan = span;
			}
		}
	}

	return bestPack;
}

static int DrawLevelOvr2P_IsNativeLevelSpan(uintptr_t ptr, uintptr_t size)
{
	if (size == 0)
	{
		return 0;
	}

	const struct Mempack *pack = DrawLevelOvr2P_FindMempackContaining(ptr);
	if (pack == NULL)
	{
		return 0;
	}

	uintptr_t end = ptr + size;
	if (end < ptr)
	{
		return 0;
	}

	uintptr_t span;
	if (!DrawLevelOvr2P_MempackContains(pack, ptr, &span))
	{
		return 0;
	}

	return end <= (uintptr_t)pack->start + span;
}

