static int Ovr227_800a48dc_Ground4x1RenderedSelectorNearGate(struct PushBuffer *pb, struct PrimMem *primMem, struct DrawLevelOvrScratchVertex *projected,
                                                             struct QuadBlock *block, int faceIndex)
{
	int indices[4];
	u32 directMask = 0;

	u32 tableWord = DrawLevelOvr2P_Select4x1ProjectedFace(projected, block, faceIndex, indices);
	if (DrawLevelOvr2P_IsProjectedFaceFullyNear(projected, indices))
	{
		return 1;
	}

	if (DrawLevelOvr2P_HasProjectedVertexNear(projected, indices, 4))
	{
		directMask = OVR227_DIRECT_QUAD;
		DrawLevelOvr2P_Scratch()->directMask = directMask;
	}
	else if (!Ovr227_800a3d60_SelectAndStoreGround4x1SelectorDirectMask(projected, indices, tableWord, &directMask))
	{
		return 1;
	}

	Ovr227_800a4a38_StoreGround4x1RenderedClipHeader(tableWord);
	u32 maxDepth = DrawLevelOvr2P_GetProjectedMaxDepth(projected, indices);
	uint32_t *inheritedOtEntry = Ovr227_800a4a60_ResolveGround4x1RenderedOtEntry(pb, block, projected, maxDepth, faceIndex);
	struct TextureLayout *texture = Ovr227_800a4ac8_SelectGround4x1RenderedTexture(block, projected, maxDepth);
	if (texture != NULL)
	{
		Ovr227_800a4b04_WriteGround4x1RenderedUv(projected, indices, texture, tableWord);
	}

	return Ovr227_800a4ba4_Ground4x1RenderedNearOrDirect(pb, primMem, block, projected, indices, faceIndex, texture, 0, OVR227_TOP_LEVEL_NEAR_DEPTH_THRESHOLD, inheritedOtEntry);
}

