static int Ovr227_800a5384_DispatchGround4x2DeepestCompact(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                           const struct DrawLevelOvrScratchVertex *projected, int faceIndex,
                                                           const struct TextureLayout *texture, int depth, int handlerSlot, int inheritedOtIndex)
{
	const struct DrawLevelOvrNearSubdivisionCase *subdivisionCase = DrawLevelOvr2P_GetDeepestGridCompactCase(handlerSlot);

	for (s32 subdivisionIndex = 0; subdivisionIndex < 2; subdivisionIndex++)
	{
		int subIndices[4];

		for (s32 vertexIndex = 0; vertexIndex < 4; vertexIndex++)
		{
			subIndices[vertexIndex] = subdivisionCase->subIndices[subdivisionIndex][vertexIndex];
		}

		if (subdivisionCase->slotWords[subdivisionIndex] != OVR227_SLOT_WORD_PRESERVE)
		{
			DrawLevelOvr2P_SetGridFaceSlotWord(projected, subdivisionCase->slotWords[subdivisionIndex]);
		}

		if (!Ovr227_800a58d4_Ground4x2DirectPreflight(pb, primMem, block, projected, subIndices, faceIndex, texture, depth,
		                                              subdivisionCase->directMasks[subdivisionIndex], inheritedOtIndex))
		{
			return 0;
		}
	}

	return 1;
}

