static int Ovr227_800a5c00_Ground4x2NearOrDirect(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                 const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                 const struct TextureLayout *texture, int depth, u32 threshold, int inheritedOtIndex)
{
	u32 nearMask = DrawLevelOvr2P_GetProjectedNearMaskAtThreshold(projected, indices, threshold);

	if (nearMask == 0)
	{
		return Ovr227_800a5dcc_DispatchGround4x2DirectTail(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtIndex);
	}

	struct DrawLevelOvrScratchVertex *sub = DrawLevelOvr2P_GetSubdivisionFrame(depth);
	Ovr227_800a57bc_BuildGround4x2ListSubdivisionFrame(sub, projected, indices);

	u32 handlerAddress = *CTR_SCRATCHPAD_PTR(u32, DRAW_LEVEL_OVR_DIRECT_NEAR_HANDLER_TABLE_OFFSET + nearMask);
	int handlerSlot = DrawLevelOvr2P_GetNearSubdivisionTableSlot(nearMask);
	DrawLevelOvr2P_SetPreviousRecursiveHandler(handlerAddress);

	return Ovr227_800a5384_DispatchGround4x2HelperWrappers(pb, primMem, block, sub, faceIndex, texture, depth + 1, handlerAddress, handlerSlot,
	                                                       inheritedOtIndex);
}

static void Ovr227_800a5d14_PrepareGround4x2DeepestUv(const struct DrawLevelOvrScratchVertex *projected, const int *indices)
{
	u32 directMask = DrawLevelOvr2P_Scratch()->directMask;
	u32 handlerAddress = DrawLevelOvr2P_GetDirectHandlerAddress(directMask);

	if (handlerAddress != 0)
	{
		DrawLevelOvr2P_PrepareDeepestMosaicUv(projected, indices, handlerAddress);
	}
}

static int Ovr227_800a5d14_DispatchGround4x2Deepest(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                    const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                    const struct TextureLayout *texture, int inheritedOtIndex)
{
	Ovr227_800a5d14_PrepareGround4x2DeepestUv(projected, indices);
	int result = Ovr227_800a5dcc_DispatchGround4x2DirectTail(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtIndex);

	DrawLevelOvr2P_RestoreProjectedUvScratch();
	return result;
}

static uint32_t *Ovr227_800a5ef8_ResolveGround4x2DirectOtEntry(struct PushBuffer *pb, int inheritedOtIndex)
{
	if (inheritedOtIndex < 0)
	{
		return NULL;
	}

	return &pb->ptrOT[inheritedOtIndex];
}

static int Ovr227_800a5dd4_EmitGround4x2GT3Raw(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                               const struct DrawLevelOvrScratchVertex *projected, const int *indices, const struct TextureLayout *texture,
                                               int inheritedOtIndex, int secondary)
{
	int triIndices[3];
	uint32_t *otEntry = Ovr227_800a5ef8_ResolveGround4x2DirectOtEntry(pb, inheritedOtIndex);

	if (otEntry == NULL)
	{
		return 1;
	}

	if (secondary)
	{
		triIndices[0] = indices[1];
		triIndices[1] = indices[3];
		triIndices[2] = indices[2];
	}
	else
	{
		triIndices[0] = indices[0];
		triIndices[1] = indices[1];
		triIndices[2] = indices[2];
	}

	return DrawLevelOvr2P_EmitPreparedProjectedTriRawCodeAtOtEntry(pb, primMem, block, projected, triIndices, texture, otEntry,
	                                                               OVR227_PRIM_CODE_AUTO);
}

static int Ovr227_800a5e58_EmitGround4x2GT4Raw(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                               const struct DrawLevelOvrScratchVertex *projected, const int *indices, const struct TextureLayout *texture,
                                               int inheritedOtIndex)
{
	uint32_t *otEntry = Ovr227_800a5ef8_ResolveGround4x2DirectOtEntry(pb, inheritedOtIndex);

	if (otEntry == NULL)
	{
		return 1;
	}

	return DrawLevelOvr2P_EmitPreparedProjectedQuadRawCodeAtOtEntry(pb, primMem, block, projected, indices, texture, otEntry, OVR227_PRIM_CODE_AUTO);
}

static int Ovr227_800a5dcc_DispatchGround4x2DirectTail(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                       const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                       const struct TextureLayout *texture, int inheritedOtIndex)
{
	u32 directMask = DrawLevelOvr2P_Scratch()->directMask;
	u32 handlerAddress = DrawLevelOvr2P_GetDirectHandlerAddress(directMask);

	(void)faceIndex;

	switch (handlerAddress)
	{
	case DRAW_LEVEL_OVR_RETAIL_LABEL_GROUND_4X2_LIST_DIRECT_GT3_PRIMARY:
		return Ovr227_800a5dd4_EmitGround4x2GT3Raw(pb, primMem, block, projected, indices, texture, inheritedOtIndex, 0);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_GROUND_4X2_LIST_DIRECT_GT3_SECOND:
		return Ovr227_800a5dd4_EmitGround4x2GT3Raw(pb, primMem, block, projected, indices, texture, inheritedOtIndex, 1);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_GROUND_4X2_LIST_DIRECT_GT4:
		return Ovr227_800a5e58_EmitGround4x2GT4Raw(pb, primMem, block, projected, indices, texture, inheritedOtIndex);
	default:
		return 1;
	}
}

static int Ovr227_800a59c0_Ground4x2SelectorNearGate(struct PushBuffer *pb, struct PrimMem *primMem, struct DrawLevelOvrScratchVertex *projected,
                                                     struct QuadBlock *block, int faceIndex)
{
	int indices[4];
	u32 directMask = 0;

	u32 tableWord = DrawLevelOvr2P_Select4x1ProjectedFace(projected, block, faceIndex, indices);
	if (!Ovr227_800a3d60_SelectAndStoreGround4x1SelectorDirectMask(projected, indices, tableWord, &directMask))
	{
		return 1;
	}

	u32 maxDepth = DrawLevelOvr2P_GetProjectedMaxDepth(projected, indices);
	int inheritedOtIndex = Ovr227_800a3e88_ResolveGround4x1SelectorOtIndex(block, projected, maxDepth, faceIndex);
	struct TextureLayout *texture = Ovr227_800a3ef0_SelectGround4x1SelectorTexture(block, projected, maxDepth);
	if (texture != NULL)
	{
		DrawLevelOvr2P_WriteProjectedUv(projected, indices, texture, tableWord);
	}

	return Ovr227_800a5c00_Ground4x2NearOrDirect(pb, primMem, block, projected, indices, faceIndex, texture, 0, OVR227_TOP_LEVEL_NEAR_DEPTH_THRESHOLD, inheritedOtIndex);
}

