static int Ovr227_800a7a44_DispatchDynamicListDeepest(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                      const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                      const struct TextureLayout *texture, int inheritedOtIndex)
{
	Ovr227_800a7a44_PrepareDynamicListDeepestUv(projected, indices);
	int result = Ovr227_800a7afc_DispatchDynamicListDirectTail(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtIndex);

	DrawLevelOvr2P_RestoreProjectedUvScratch();
	return result;
}

