static int Ovr227_800a6aa8_Ground4x2RenderedNearOrDirect(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                         const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                         const struct TextureLayout *texture, int depth, u32 threshold, uint32_t *inheritedOtEntry)
{
	u32 nearMask = DrawLevelOvr2P_GetProjectedNearMaskAtThreshold(projected, indices, threshold);

	if (nearMask == 0)
	{
		return Ovr227_800a6c64_DispatchGround4x2RenderedDirectTail(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtEntry);
	}

	struct DrawLevelOvrScratchVertex *sub = DrawLevelOvr2P_GetSubdivisionFrame(depth);
	Ovr227_800a65d0_BuildGround4x2RenderedSubdivisionFrame(sub, projected, indices);

	u32 handlerAddress = *CTR_SCRATCHPAD_PTR(u32, DRAW_LEVEL_OVR_DIRECT_NEAR_HANDLER_TABLE_OFFSET + nearMask);
	int handlerSlot = DrawLevelOvr2P_GetNearSubdivisionTableSlot(nearMask);
	DrawLevelOvr2P_SetPreviousRecursiveHandler(handlerAddress);

	return Ovr227_800a6280_DispatchGround4x2RenderedHelperWrappers(pb, primMem, block, sub, faceIndex, texture, depth + 1, handlerAddress, handlerSlot,
	                                                               inheritedOtEntry);
}

static int Ovr227_800a66dc_Ground4x2RenderedPreflight(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                      const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                      const struct TextureLayout *texture, int depth, u32 allowedMask, uint32_t *inheritedOtEntry)
{
	u32 directMask = 0;

	if (DrawLevelOvr2P_IsProjectedFaceFullyNear(projected, indices))
	{
		return 1;
	}

	if (DrawLevelOvr2P_HasProjectedVertexNear(projected, indices, 4))
	{
		directMask = OVR227_DIRECT_QUAD;
		DrawLevelOvr2P_Scratch()->directMask = directMask;
	}
	else if (!Ovr227_800a3c74_SelectAndStoreGround4x1DirectMask(projected, indices, allowedMask, &directMask))
	{
		return 1;
	}

	if (DrawLevelOvr2P_IsDeepestSubdivisionFrame(projected))
	{
		return Ovr227_800a6bac_DispatchGround4x2RenderedDeepest(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtEntry);
	}

	return Ovr227_800a6aa8_Ground4x2RenderedNearOrDirect(pb, primMem, block, projected, indices, faceIndex, texture, depth, OVR227_RECURSIVE_NEAR_DEPTH_THRESHOLD, inheritedOtEntry);
}

static int Ovr227_800a6320_DispatchGround4x2RenderedDeepestCompact(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                                   const struct DrawLevelOvrScratchVertex *projected, int faceIndex,
                                                                   const struct TextureLayout *texture, int depth, int handlerSlot, uint32_t *inheritedOtEntry)
{
	const struct DrawLevelOvrNearSubdivisionCase *subdivisionCase = DrawLevelOvr2P_GetDeepestGridCompactCase(handlerSlot);

	for (s32 subdivisionIndex = 0; subdivisionIndex < 2; subdivisionIndex++)
	{
		int subIndices[4];

		for (s32 vertexIndex = 0; vertexIndex < 4; vertexIndex++)
		{
			subIndices[vertexIndex] = subdivisionCase->subIndices[subdivisionIndex][vertexIndex];
		}

		if (subdivisionCase->slotWords[subdivisionIndex] != OVR227_SLOT_WORD_PRESERVE)
		{
			DrawLevelOvr2P_SetGridFaceSlotWord(projected, subdivisionCase->slotWords[subdivisionIndex]);
		}

		if (!Ovr227_800a66dc_Ground4x2RenderedPreflight(pb, primMem, block, projected, subIndices, faceIndex, texture, depth,
		                                                subdivisionCase->directMasks[subdivisionIndex], inheritedOtEntry))
		{
			return 0;
		}
	}

	return 1;
}

