static int Ovr227_800a87b0_DispatchDynamicRenderedDeepest(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                          const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                          const struct TextureLayout *texture, uint32_t *inheritedOtEntry)
{
	Ovr227_800a87b0_PrepareDynamicRenderedDeepestUv(projected, indices);
	int result = Ovr227_800a8868_DispatchDynamicRenderedDirectTail(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtEntry);

	DrawLevelOvr2P_RestoreProjectedUvScratch();
	return result;
}

static int Ovr227_800a86cc_DynamicRenderedNearOrDirect(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                       const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                       const struct TextureLayout *texture, int depth, u32 threshold, uint32_t *inheritedOtEntry)
{
	u32 nearMask = DrawLevelOvr2P_GetProjectedNearMaskAtThreshold(projected, indices, threshold);

	if (nearMask == 0)
	{
		return Ovr227_800a8868_DispatchDynamicRenderedDirectTail(pb, primMem, block, projected, indices, faceIndex, texture, inheritedOtEntry);
	}

	struct DrawLevelOvrScratchVertex *sub = DrawLevelOvr2P_GetSubdivisionFrame(depth);
	Ovr227_800a81f4_BuildDynamicRenderedSubdivisionFrame(sub, projected, indices);

	u32 handlerAddress = *CTR_SCRATCHPAD_PTR(u32, DRAW_LEVEL_OVR_DIRECT_NEAR_HANDLER_TABLE_OFFSET + nearMask);
	int handlerSlot = DrawLevelOvr2P_GetNearSubdivisionTableSlot(nearMask);
	DrawLevelOvr2P_SetPreviousRecursiveHandler(handlerAddress);

	return Ovr227_800a7fb0_DispatchDynamicRenderedHelperWrappers(pb, primMem, block, sub, faceIndex, texture, depth + 1, handlerAddress, handlerSlot,
	                                                             inheritedOtEntry);
}

