static int Ovr227_800aa62c_WriteQuad4x4RenderedClippedRecordAtOtEntry(struct PushBuffer *pb, const struct QuadBlock *block,
                                                                      const struct DrawLevelOvrScratchVertex *projected, const int *indices, int count,
                                                                      uint32_t *otEntry)
{
	u8 *cursor = DrawLevelOvr2P_GetClipRecordCursor();
	size_t recordSize = DrawLevelOvr2P_GetClipRecordSize(count);

	(void)pb;

	if (otEntry == NULL)
	{
		return 1;
	}

	if (!DrawLevelOvr2P_ShouldWriteRenderedClippedRecord(projected, indices, count))
	{
		return 1;
	}

	struct DrawLevelOvrClipRecord *record = (struct DrawLevelOvrClipRecord *)cursor;
	record->header = DrawLevelOvr2P_GetRenderedClipRecordHeader(block, count);
	record->otEntry = (u32)(uintptr_t)otEntry;
	record->tpage = DrawLevelOvr2P_Scratch()->uv.tpage;
	record->clut = DrawLevelOvr2P_Scratch()->uv.clut;

	for (s32 vertexIndex = 0; vertexIndex < count; vertexIndex++)
	{
		DrawLevelOvr2P_CopyClipRecordVertex(&record->vertex[vertexIndex], &projected[indices[vertexIndex]]);
	}

	DrawLevelOvr2P_SetClipRecordCursor(cursor + recordSize);
	return 1;
}

static int Ovr227_800aa474_EmitQuad4x4RenderedGT3RawOrClip(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                           const struct DrawLevelOvrScratchVertex *projected, const int *indices,
                                                           const struct TextureLayout *texture, uint32_t *inheritedOtEntry, int secondary)
{
	int triIndices[3];

	if (inheritedOtEntry == NULL)
	{
		return 1;
	}

	if (secondary)
	{
		triIndices[0] = indices[1];
		triIndices[1] = indices[3];
		triIndices[2] = indices[2];
	}
	else
	{
		triIndices[0] = indices[0];
		triIndices[1] = indices[1];
		triIndices[2] = indices[2];
	}

	if (DrawLevelOvr2P_AreProjectedVerticesHalfNearSigned(projected, triIndices, 3))
	{
		return 1;
	}

	if (DrawLevelOvr2P_HasProjectedVertexNearSigned(projected, triIndices, 3))
	{
		return Ovr227_800aa62c_WriteQuad4x4RenderedClippedRecordAtOtEntry(pb, block, projected, triIndices, 3, inheritedOtEntry);
	}

	return DrawLevelOvr2P_EmitPreparedProjectedTriRawCodeAtOtEntry(pb, primMem, block, projected, triIndices, texture, inheritedOtEntry,
	                                                               OVR227_PRIM_CODE_AUTO);
}

static int Ovr227_800aa528_EmitQuad4x4RenderedGT4RawOrClip(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                           const struct DrawLevelOvrScratchVertex *projected, const int *indices,
                                                           const struct TextureLayout *texture, uint32_t *inheritedOtEntry)
{
	if (inheritedOtEntry == NULL)
	{
		return 1;
	}

	if (DrawLevelOvr2P_AreProjectedVerticesHalfNear(projected, indices, 4))
	{
		return 1;
	}

	if (DrawLevelOvr2P_HasProjectedVertexNear(projected, indices, 4))
	{
		return Ovr227_800aa62c_WriteQuad4x4RenderedClippedRecordAtOtEntry(pb, block, projected, indices, 4, inheritedOtEntry);
	}

	return DrawLevelOvr2P_EmitPreparedProjectedQuadRawCodeAtOtEntry(pb, primMem, block, projected, indices, texture, inheritedOtEntry,
	                                                                OVR227_PRIM_CODE_AUTO);
}

static int Ovr227_800aa46c_DispatchQuad4x4RenderedDirectTail(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                             const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                             const struct TextureLayout *texture, uint32_t *inheritedOtEntry)
{
	u32 directMask = DrawLevelOvr2P_Scratch()->directMask;
	u32 handlerAddress = DrawLevelOvr2P_GetDirectHandlerAddress(directMask);

	(void)faceIndex;

	switch (handlerAddress)
	{
	case DRAW_LEVEL_OVR_RETAIL_LABEL_QUAD_4X4_RENDERED_DIRECT_GT3_PRIMARY:
		return Ovr227_800aa474_EmitQuad4x4RenderedGT3RawOrClip(pb, primMem, block, projected, indices, texture, inheritedOtEntry, 0);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_QUAD_4X4_RENDERED_DIRECT_GT3_SECOND:
		return Ovr227_800aa474_EmitQuad4x4RenderedGT3RawOrClip(pb, primMem, block, projected, indices, texture, inheritedOtEntry, 1);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_QUAD_4X4_RENDERED_DIRECT_GT4:
		return Ovr227_800aa528_EmitQuad4x4RenderedGT4RawOrClip(pb, primMem, block, projected, indices, texture, inheritedOtEntry);
	default:
		return 1;
	}
}

