	return Ovr227_800aa2d0_Quad4x4RenderedNearOrDirect(pb, primMem, block, projected, indices, faceIndex, texture, depth, OVR227_RECURSIVE_NEAR_DEPTH_THRESHOLD, inheritedOtEntry);
