static int Ovr227_800aa034_Quad4x4RenderedSelectorNearGate(struct PushBuffer *pb, struct PrimMem *primMem, struct DrawLevelOvrScratchVertex *projected,
                                                           struct QuadBlock *block, int faceIndex)
{
	int indices[4];
	u32 directMask = 0;

	u32 tableWord = DrawLevelOvr2P_Select4x1ProjectedFace(projected, block, faceIndex, indices);
	if (DrawLevelOvr2P_IsProjectedFaceFullyNear(projected, indices))
	{
		return 1;
	}

	if (DrawLevelOvr2P_HasProjectedVertexNear(projected, indices, 4))
	{
		directMask = OVR227_DIRECT_QUAD;
		DrawLevelOvr2P_Scratch()->directMask = directMask;
	}
	else if (!Ovr227_800a3d60_SelectAndStoreGround4x1SelectorDirectMask(projected, indices, tableWord, &directMask))
	{
		return 1;
	}

	Ovr227_800aa190_StoreQuad4x4RenderedClipHeader(tableWord);
	u32 maxDepth = DrawLevelOvr2P_GetProjectedMaxDepth(projected, indices);
	uint32_t *inheritedOtEntry = Ovr227_800aa1b8_ResolveQuad4x4RenderedOtEntry(pb, block, projected, maxDepth, faceIndex);
	struct TextureLayout *texture = Ovr227_800aa220_SelectQuad4x4RenderedTexture(block, projected, maxDepth);
	if (texture != NULL)
	{
		Ovr227_800aa258_WriteQuad4x4RenderedUv(projected, indices, texture, tableWord);
	}

	return Ovr227_800aa2d0_Quad4x4RenderedNearOrDirect(pb, primMem, block, projected, indices, faceIndex, texture, 0, OVR227_TOP_LEVEL_NEAR_DEPTH_THRESHOLD, inheritedOtEntry);
}

