static struct TextureLayout *Ovr227_800a1174_PrepareFullDynamicLowUv(struct QuadBlock *block, struct DrawLevelOvrScratchVertex *projected)
{
	const int *indices = sDrawLevelOvr2PFullDynamicLowIndices;
	struct TextureLayout *texture = block->ptr_texture_low;

	// NOTE(aalhendi): Retail full-dynamic 0x800a0ef4 seeds low-LOD UVs before
	// choosing either the direct low quad or the near/transition helper table.
	DrawLevelOvr2P_Scratch()->selected4x1TableWord = 0;

	u32 uv0 = DrawLevelOvr2P_ReadWord(texture, 0);
	u32 uv1 = DrawLevelOvr2P_ReadWord(texture, 4);
	u32 uv2 = DrawLevelOvr2P_ReadWord(texture, 8);
	DrawLevelOvr2P_Scratch()->uv.uv0 = uv0;
	DrawLevelOvr2P_Scratch()->uv.uv1 = uv1;
	DrawLevelOvr2P_Scratch()->uv.uv2 = uv2;
	projected[indices[0]].flags = (u16)uv0;
	projected[indices[1]].flags = (u16)uv1;
	projected[indices[2]].flags = (u16)uv2;
	projected[indices[3]].flags = (u16)(uv2 >> 16);

	return texture;
}

static u16 DrawLevelOvr2P_AverageFullDynamicUv(u16 uvA, u16 uvB)
{
	u8 u = (u8)((((u32)uvA & 0xff) + ((u32)uvB & 0xff)) >> 1);
	u8 v = (u8)((((u32)uvA >> 8) + ((u32)uvB >> 8)) >> 1);

	return DrawLevelOvr2P_PackUv(u, v);
}

static void DrawLevelOvr2P_AdjustFullDynamicMidUvs(struct DrawLevelOvrScratchVertex *projected)
{
	projected[4].flags = DrawLevelOvr2P_AverageFullDynamicUv(projected[0].flags, projected[1].flags);
	projected[5].flags = DrawLevelOvr2P_AverageFullDynamicUv(projected[0].flags, projected[2].flags);
	projected[6].flags = DrawLevelOvr2P_AverageFullDynamicUv(projected[1].flags, projected[2].flags);
	projected[7].flags = DrawLevelOvr2P_AverageFullDynamicUv(projected[1].flags, projected[3].flags);
	projected[8].flags = DrawLevelOvr2P_AverageFullDynamicUv(projected[2].flags, projected[3].flags);
}

static int DrawLevelOvr2P_DispatchFullDynamicHelperSequence(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                            struct DrawLevelOvrScratchVertex *projected, DrawLevelOvrRetailLabel handlerAddress,
                                                            struct TextureLayout *texture, int depth);

static int Ovr227_800a1dec_EmitFullDynamicGT3Raw(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                 struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                 struct TextureLayout *texture, int secondary)
{
	int triIndices[3];

	if (secondary)
	{
		triIndices[0] = indices[1];
		triIndices[1] = indices[3];
		triIndices[2] = indices[2];
	}
	else
	{
		triIndices[0] = indices[0];
		triIndices[1] = indices[1];
		triIndices[2] = indices[2];
	}

	return DrawLevelOvr2P_EmitPreparedProjectedTriRawCodeAtOt(pb, primMem, block, projected, triIndices, faceIndex, texture, 0,
	                                                          sDrawLevelOvr2P_FullDynamicInheritedOtIndex, OVR227_PRIM_CODE_AUTO);
}

static int Ovr227_800a1e70_EmitFullDynamicGT4Raw(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                 struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                 struct TextureLayout *texture)
{
	return DrawLevelOvr2P_EmitPreparedProjectedQuadRawCodeAtOt(pb, primMem, block, projected, indices, faceIndex, texture, 0,
	                                                           sDrawLevelOvr2P_FullDynamicInheritedOtIndex, OVR227_PRIM_CODE_AUTO);
}

static int Ovr227_800a1dc8_EmitFullDynamicDirectTail(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                     struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                     struct TextureLayout *texture)
{
	u32 directMask = DrawLevelOvr2P_Scratch()->directMask;
	DrawLevelOvrRetailLabel handlerAddress = DrawLevelOvr2P_GetDirectHandlerAddress(directMask);

	switch (handlerAddress)
	{
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_PRIMARY_226:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_PRIMARY_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_PRIMARY_229:
		return Ovr227_800a1dec_EmitFullDynamicGT3Raw(pb, primMem, block, projected, indices, faceIndex, texture, 0);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_SECOND_226:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_SECOND_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_SECOND_229:
		return Ovr227_800a1dec_EmitFullDynamicGT3Raw(pb, primMem, block, projected, indices, faceIndex, texture, 1);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT4_226:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT4_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT4_229:
		return Ovr227_800a1e70_EmitFullDynamicGT4Raw(pb, primMem, block, projected, indices, faceIndex, texture);
	default:
		return 1;
	}
}

static int Ovr227_800a1dc8_IsSplitGroundListADirectHandler(DrawLevelOvrRetailLabel handlerAddress)
{
	switch (handlerAddress)
	{
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_PRIMARY_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_SECOND_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT4_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_PRIMARY_229:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT3_SECOND_229:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_FULL_DYNAMIC_DIRECT_GT4_229:
		return 1;
	default:
		return 0;
	}
}

static int Ovr227_800a1dc8_EmitFullDynamicDeepestDirectTail(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                            struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                            struct TextureLayout *texture)
{
	DrawLevelOvrRetailLabel handlerAddress = DrawLevelOvr2P_GetDirectHandlerAddress(DrawLevelOvr2P_Scratch()->directMask);

	if (!Ovr227_800a1dc8_IsSplitGroundListADirectHandler(handlerAddress))
	{
		return Ovr227_800a1dc8_EmitFullDynamicDirectTail(pb, primMem, block, projected, indices, faceIndex, texture);
	}

	DrawLevelOvr2P_PrepareDeepestMosaicUv(projected, indices, handlerAddress);
	int result = Ovr227_800a1dc8_EmitFullDynamicDirectTail(pb, primMem, block, projected, indices, faceIndex, texture);
	DrawLevelOvr2P_RestoreProjectedUvScratch();
	return result;
}

static u32 Ovr227_800a1cf0_SelectFullDynamicNearMask(const struct DrawLevelOvrScratchVertex *projected, const int *indices, u32 threshold)
{
	return DrawLevelOvr2P_GetProjectedNearMaskAtThreshold(projected, indices, threshold);
}

static int Ovr227_800a1cf0_DispatchFullDynamicNearSubdivision(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                              struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                              struct TextureLayout *texture, int depth, u32 directMask, u32 threshold)
{
	(void)directMask;
	u32 nearMask = Ovr227_800a1cf0_SelectFullDynamicNearMask(projected, indices, threshold);
	if (nearMask == 0)
	{
		return Ovr227_800a1dc8_EmitFullDynamicDirectTail(pb, primMem, block, projected, indices, faceIndex, texture);
	}

	if (depth >= OVR227_MAX_NEAR_SUBDIV_DEPTH)
	{
		return Ovr227_800a1dc8_EmitFullDynamicDirectTail(pb, primMem, block, projected, indices, faceIndex, texture);
	}

	DrawLevelOvrRetailLabel handlerAddress = DrawLevelOvr2P_GetNearSubdivisionHandlerAddress(nearMask, OVR227_CLIP_BYTES_LIST);
	DrawLevelOvr2P_SetPreviousRecursiveHandler(handlerAddress);

	struct DrawLevelOvrScratchVertex *sub = DrawLevelOvr2P_GetSubdivisionFrame(depth);
	Ovr227_800a18ec_BuildFullDynamicSubdivisionFrame(sub, projected, indices);

	return DrawLevelOvr2P_DispatchFullDynamicHelperSequence(pb, primMem, block, sub, handlerAddress, texture, depth + 1);
}

static int DrawLevelOvr2P_EmitFullDynamicTerminalFaceSlotMode(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                              struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                              struct TextureLayout *texture, int depth, u32 allowedMask, int updateSlot)
{
	struct DrawLevelOvrFullDynamicRecursiveGate gate;

	if (updateSlot)
	{
		DrawLevelOvr2P_SetGridFaceSlot(projected, faceIndex);
	}

	// NOTE(aalhendi): Retail 0x800a18c0..0x800a19a8 owns the full-dynamic
	// packed-SXY cull, direct-mask fold, max-recursion direct handoff, and
	// recursive scratch 0x28 near-threshold selection.
	if (!Ovr227_800a19d4_FullDynamicRecursiveGate(projected, indices, allowedMask, &gate))
	{
		return 1;
	}

	if (gate.forceDirect)
	{
		return Ovr227_800a1dc8_EmitFullDynamicDeepestDirectTail(pb, primMem, block, projected, indices, faceIndex, texture);
	}

	return Ovr227_800a1cf0_DispatchFullDynamicNearSubdivision(pb, primMem, block, projected, indices, faceIndex, texture, depth, gate.directMask, 0x28);
}

static int DrawLevelOvr2P_EmitFullDynamicTerminalFacePreserveSlot(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                                  struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                                  struct TextureLayout *texture, int depth, u32 allowedMask)
{
	return DrawLevelOvr2P_EmitFullDynamicTerminalFaceSlotMode(pb, primMem, block, projected, indices, faceIndex, texture, depth, allowedMask, 0);
}

static int Ovr227_800a1abc_SelectFullDynamicDirectSlot(struct QuadBlock *block, struct DrawLevelOvrScratchVertex *projected, int faceIndex, int *indices,
                                                       struct TextureLayout **texture, u32 *directMask)
{
	u32 tableWord = DrawLevelOvr2P_Select4x1ProjectedFace(projected, block, faceIndex, indices);

	if (DrawLevelOvr2P_IsProjectedPolyOffscreenPacked(projected, indices, 4))
	{
		return 0;
	}

	*directMask = DrawLevelOvr2P_SelectDirectMask(block, projected, indices, tableWord, OVR227_DIRECT_QUAD);
	DrawLevelOvr2P_Scratch()->directMask = *directMask;
	if (*directMask == 0)
	{
		return 0;
	}

	u32 maxDepth = DrawLevelOvr2P_GetProjectedMaxDepth(projected, indices);
	DrawLevelOvr2P_SetFullDynamicInheritedOtIndex(block, projected, maxDepth, faceIndex);
	*texture = DrawLevelOvr2P_GetProjectedMidTexture(block, projected, faceIndex, maxDepth);

	if (*texture != NULL)
	{
		DrawLevelOvr2P_WriteProjectedUv(projected, indices, *texture, tableWord);
	}

	return 1;
}

static int DrawLevelOvr2P_EmitFullDynamicSelectorFace(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                      struct DrawLevelOvrScratchVertex *projected, int faceIndex, int depth)
{
	struct TextureLayout *texture = NULL;
	int indices[4];
	u32 directMask;

	// NOTE(aalhendi): Retail 0x800a19a8..0x800a1be8 selects the top-level
	// full-dynamic face slot, rejects empty direct masks before texture/UV
	// selection, and uses scratch 0x24 for the first near-mask handoff.
	if (!Ovr227_800a1abc_SelectFullDynamicDirectSlot(block, projected, faceIndex, indices, &texture, &directMask))
	{
		return 1;
	}

	return Ovr227_800a1cf0_DispatchFullDynamicNearSubdivision(pb, primMem, block, projected, indices, faceIndex, texture, depth, directMask, 0x24);
}

