static int Ovr227_800a16e8_FullDynamicHelperSlot0(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                  struct DrawLevelOvrScratchVertex *projected, struct TextureLayout *texture, int depth)
{
	//Retail 0x800a15d4 does not call the shared Face1/Face2
	// emitters. It inlines its own index sets, closing both sub-quads on corner
	// vertex 3 instead of on edge midpoints 7 and 8:
	//   0x800a15d4: fp+80,20,120,60  -> {4,1,6,3} == GridMixedFaceIndices[0]
	//   0x800a15ec: fp+100,120,40,60 -> {5,6,2,3} == GridMixedFaceIndices[1]
	//   0x800a160c: b 0x800a1534     -> {0,4,5,6} == GridFaceIndices[0]
	// Face1/Face2 stop at those midpoints, so the two sub-quads came out half
	// height and the wedge against corner 3 was emitted by nothing. The
	// projected-grid family already uses this Mixed[0]/Mixed[1]/GridFace[0]
	// sequence for the same near-mask slot.
	if (!DrawLevelOvr2P_EmitFullDynamicTerminalFacePreserveSlot(pb, primMem, block, projected, sDrawLevelOvr2PGridMixedFaceIndices[0], 0, texture, depth,
	                                                           OVR227_DIRECT_QUAD))
	{
		return 0;
	}
	if (!DrawLevelOvr2P_EmitFullDynamicTerminalFacePreserveSlot(pb, primMem, block, projected, sDrawLevelOvr2PGridMixedFaceIndices[1], 0, texture, depth,
	                                                           OVR227_DIRECT_QUAD))
	{
		return 0;
	}
	return Ovr227_800a1648_EmitFullDynamicFace0(pb, primMem, block, projected, texture, depth, OVR227_DIRECT_QUAD);
}

