static int DrawLevelOvr2P_NonWaterRenderedSelectorNearGate(struct PushBuffer *pb, struct PrimMem *primMem, struct DrawLevelOvrScratchVertex *projected,
                                                           struct QuadBlock *block, int faceIndex, int role)
{
	switch (role)
	{
	case DRAW_LEVEL_OVR_BUCKET_4X1_RENDERED:
		return Ovr227_800a48dc_Ground4x1RenderedSelectorNearGate(pb, primMem, projected, block, faceIndex);

	case DRAW_LEVEL_OVR_BUCKET_4X2_RENDERED:
		return Ovr227_800a680c_Ground4x2RenderedSelectorNearGate(pb, primMem, projected, block, faceIndex);

	case DRAW_LEVEL_OVR_BUCKET_DYNAMIC_RENDERED:
		return Ovr227_800a8430_DynamicRenderedSelectorNearGate(pb, primMem, projected, block, faceIndex);

	default:
		return Ovr227_800aa034_Quad4x4RenderedSelectorNearGate(pb, primMem, projected, block, faceIndex);
	}
}

static int DrawLevelOvr2P_DrawNonWaterRenderedList(struct QuadBlock **renderedList, struct PushBuffer *pb, struct mesh_info *mesh, struct PrimMem *primMem,
                                                   int role)
{
	struct LevVertex *vertices = mesh->ptrVertexArray;
	struct DrawLevelOvrScratchVertex *projected = DrawLevelOvr2P_GetScratchVertices();
	u32 reserve = DrawLevelOvr2P_GetNonWaterRenderedListReserve(role);
	enum Ovr227GridSlotMode slotMode = DrawLevelOvr2P_GetNonWaterRenderedListSlotMode(role);

	if (renderedList == NULL)
	{
		return 1;
	}

	while (1)
	{
		struct QuadBlock *block = *renderedList;

		if (!DrawLevelOvr2P_HasBucketPrimReserve(primMem, reserve))
		{
			return 0;
		}

		DrawLevelOvr2P_SetGridFaceSlotWord(projected, 0);
		if (block == NULL)
		{
			return 1;
		}

		DrawLevelOvr2P_ProjectRenderedGrid(vertices, block, projected, OVR227_PROJECTED_SOURCE_POS_FLAGS, slotMode);

		for (int faceIndex = 0; faceIndex < 4; faceIndex++)
		{
			if (!DrawLevelOvr2P_NonWaterRenderedSelectorNearGate(pb, primMem, projected, block, faceIndex, role))
			{
				return 0;
			}
		}

		renderedList++;
	}
}

