static int DrawLevelOvr2P_DrawBspListQuadBlocks(struct VisMemBspListNode *slot, struct PushBuffer *pb, struct mesh_info *mesh, struct PrimMem *primMem,
                                                const int *visFaceList, int role)
{
	if (sDrawLevelOvr2P_ListHandlersSeedRenderedCursor)
	{
		DrawLevelOvr2P_SetRenderedListCursor(DrawLevelOvr2P_GetRenderedOverflowBase());
	}

	u32 reserve = DrawLevelOvr2P_GetBspListReserve(role);

	while (slot != NULL)
	{
		struct BSP *bsp = slot->bsp;
		struct QuadBlock *block = bsp->data.leaf.ptrQuadBlockArray;
		s32 quadCount = bsp->data.leaf.numQuads;

		DrawLevelOvr2P_Scratch()->quadCount = quadCount;
		Ovr227_800a1028_SeedFullDynamicVisibilityScratch(visFaceList, block);

		while (quadCount > 0)
		{
			if (!DrawLevelOvr2P_HasBucketPrimReserve(primMem, reserve))
			{
				return 0;
			}

			if (Ovr227_800a1050_ConsumeFullDynamicVisibilityBit())
			{
				if (!DrawLevelOvr2P_EmitBspListQuadBlock(pb, primMem, mesh, block, role))
				{
					return 0;
				}
			}

			block++;
			quadCount--;
			DrawLevelOvr2P_Scratch()->quadCount = quadCount;
		}

		slot = slot->next;
	}

	DrawLevelOvr2P_TerminateRenderedListCursor();
	return 1;
}

static u32 Ovr227_800a2724_SelectWaterDirectMask(const struct DrawLevelOvrScratchVertex *projected, const int *indices, u32 allowedMask)
{
	u32 directMask = 0;

	// NOTE(aalhendi): Retail 0x800a261c..0x800a2658 tests full color words at
	// scratch vertex +0x8, then masks the two water GT3 direct bits through t2.
	if ((DrawLevelOvr2P_GetProjectedColorWord(&projected[indices[0]]) | DrawLevelOvr2P_GetProjectedColorWord(&projected[indices[1]]) |
	     DrawLevelOvr2P_GetProjectedColorWord(&projected[indices[2]])) != 0)
	{
		directMask |= OVR227_DIRECT_TRI_PRIMARY;
	}

	if ((DrawLevelOvr2P_GetProjectedColorWord(&projected[indices[1]]) | DrawLevelOvr2P_GetProjectedColorWord(&projected[indices[2]]) |
	     DrawLevelOvr2P_GetProjectedColorWord(&projected[indices[3]])) != 0)
	{
		directMask |= OVR227_DIRECT_TRI_SECONDARY;
	}

	return directMask & allowedMask;
}

static u32 Ovr227_800a2724_SelectAndStoreWaterDirectMask(const struct DrawLevelOvrScratchVertex *projected, const int *indices, u32 allowedMask)
{
	u32 directMask = Ovr227_800a2724_SelectWaterDirectMask(projected, indices, allowedMask);

	DrawLevelOvr2P_Scratch()->directMask = directMask;
	return directMask;
}

static void Ovr227_800a25e0_BuildWaterListSubdivideMidpoint(struct DrawLevelOvrScratchVertex *dstA, struct DrawLevelOvrScratchVertex *dstMid,
                                                            const struct DrawLevelOvrScratchVertex *srcA, const struct DrawLevelOvrScratchVertex *srcB)
{
	const u8 *srcAUv = (const u8 *)&srcA->flags;
	const u8 *srcBUv = (const u8 *)&srcB->flags;
	u8 *dstAUv = (u8 *)&dstA->flags;
	u8 *dstMidUv = (u8 *)&dstMid->flags;
	u32 depth;

	for (s32 axisIndex = 0; axisIndex < 3; axisIndex++)
	{
		dstA->pos[axisIndex] = srcA->pos[axisIndex];
		dstMid->pos[axisIndex] = (s16)(((s32)srcA->pos[axisIndex] + (s32)srcB->pos[axisIndex]) >> 1);
	}

	CTR_GteLoadS16TripletV0(&dstMid->pos[0]);
	gte_rtps();

	for (s32 colorChannel = 0; colorChannel < 3; colorChannel++)
	{
		dstA->color_hi[colorChannel] = srcA->color_hi[colorChannel];
		dstMid->color_hi[colorChannel] = (u8)(((u32)srcA->color_hi[colorChannel] + (u32)srcB->color_hi[colorChannel]) >> 1);
	}

	for (s32 uvByte = 0; uvByte < 2; uvByte++)
	{
		dstAUv[uvByte] = srcAUv[uvByte];
		dstMidUv[uvByte] = (u8)(((u32)srcAUv[uvByte] + (u32)srcBUv[uvByte]) >> 1);
	}

	DrawLevelOvr2P_CopyProjectedScreenDepth(dstA, srcA);
	CTR_GteStoreSXY(&dstMid->posScreen[0]);
	gte_stsz(&depth);
	DrawLevelOvr2P_StoreProjectedDepthWord(dstMid, depth);
}

static void Ovr227_800a25e0_BuildWaterListSubdivisionFrame(struct DrawLevelOvrScratchVertex *sub, const struct DrawLevelOvrScratchVertex *projected,
                                                           const int *indices)
{
	Ovr227_800a25e0_BuildWaterListSubdivideMidpoint(&sub[0], &sub[4], &projected[indices[0]], &projected[indices[1]]);
	Ovr227_800a25e0_BuildWaterListSubdivideMidpoint(&sub[1], &sub[7], &projected[indices[1]], &projected[indices[3]]);
	Ovr227_800a25e0_BuildWaterListSubdivideMidpoint(&sub[2], &sub[5], &projected[indices[2]], &projected[indices[0]]);
	Ovr227_800a25e0_BuildWaterListSubdivideMidpoint(&sub[3], &sub[8], &projected[indices[3]], &projected[indices[2]]);
	Ovr227_800a25e0_BuildWaterListSubdivideMidpoint(&sub[1], &sub[6], &projected[indices[1]], &projected[indices[2]]);
}

static void Ovr227_800a30d8_BuildWaterRenderedSubdivideMidpoint(struct DrawLevelOvrScratchVertex *dstA, struct DrawLevelOvrScratchVertex *dstMid,
                                                                const struct DrawLevelOvrScratchVertex *srcA, const struct DrawLevelOvrScratchVertex *srcB)
{
	const u8 *srcAUv = (const u8 *)&srcA->flags;
	const u8 *srcBUv = (const u8 *)&srcB->flags;
	u8 *dstAUv = (u8 *)&dstA->flags;
	u8 *dstMidUv = (u8 *)&dstMid->flags;
	u32 depth;

	for (s32 axisIndex = 0; axisIndex < 3; axisIndex++)
	{
		dstA->pos[axisIndex] = srcA->pos[axisIndex];
		dstMid->pos[axisIndex] = (s16)(((s32)srcA->pos[axisIndex] + (s32)srcB->pos[axisIndex]) >> 1);
	}

	CTR_GteLoadS16TripletV0(&dstMid->pos[0]);
	gte_rtps();

	for (s32 colorChannel = 0; colorChannel < 3; colorChannel++)
	{
		dstA->color_hi[colorChannel] = srcA->color_hi[colorChannel];
		dstMid->color_hi[colorChannel] = (u8)(((u32)srcA->color_hi[colorChannel] + (u32)srcB->color_hi[colorChannel]) >> 1);
	}

	for (s32 uvByte = 0; uvByte < 2; uvByte++)
	{
		dstAUv[uvByte] = srcAUv[uvByte];
		dstMidUv[uvByte] = (u8)(((u32)srcAUv[uvByte] + (u32)srcBUv[uvByte]) >> 1);
	}

	DrawLevelOvr2P_CopyProjectedScreenDepth(dstA, srcA);
	CTR_GteStoreSXY(&dstMid->posScreen[0]);
	gte_stsz(&depth);
	DrawLevelOvr2P_SetProjectedDepth(dstMid, depth, OVR227_CLIP_BYTES_RENDERED);
}

static void Ovr227_800a30d8_BuildWaterRenderedSubdivisionFrame(struct DrawLevelOvrScratchVertex *sub, const struct DrawLevelOvrScratchVertex *projected,
                                                               const int *indices)
{
	Ovr227_800a30d8_BuildWaterRenderedSubdivideMidpoint(&sub[0], &sub[4], &projected[indices[0]], &projected[indices[1]]);
	Ovr227_800a30d8_BuildWaterRenderedSubdivideMidpoint(&sub[1], &sub[7], &projected[indices[1]], &projected[indices[3]]);
	Ovr227_800a30d8_BuildWaterRenderedSubdivideMidpoint(&sub[2], &sub[5], &projected[indices[2]], &projected[indices[0]]);
	Ovr227_800a30d8_BuildWaterRenderedSubdivideMidpoint(&sub[3], &sub[8], &projected[indices[3]], &projected[indices[2]]);
	Ovr227_800a30d8_BuildWaterRenderedSubdivideMidpoint(&sub[1], &sub[6], &projected[indices[1]], &projected[indices[2]]);
}

static int Ovr227_800a26c8_WaterListFaceGate(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                             const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex, int depth, u32 allowedMask,
                                             uint32_t *inheritedOtEntry);

static const int *Ovr227_800a239c_GetWaterListLeafWrapperIndices(DrawLevelOvrRetailLabel handlerLabel)
{
	// NOTE(aalhendi): Retail water-list leaf wrappers 0x800a22a4..0x800a2330
	// are contiguous 0x14-byte labels selecting Face[0..3], then Extra[0..3].
	if ((handlerLabel < DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_LEAF_FACE0) || (handlerLabel > DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_LEAF_EXTRA3))
	{
		return NULL;
	}

	u32 offset = handlerLabel - DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_LEAF_FACE0;
	if ((offset % DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_STRIDE) != 0)
	{
		return NULL;
	}

	u32 index = offset / DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_STRIDE;
	if (index < 4)
	{
		return sDrawLevelOvr2PGridFaceIndices[index];
	}

	return sDrawLevelOvr2PGridExtraFaceIndices[index - 4];
}

static int Ovr227_800a239c_DispatchWaterListHelperWrappers(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                           const struct DrawLevelOvrScratchVertex *projected, int faceIndex, int depth,
                                                           DrawLevelOvrRetailLabel handlerLabel, int handlerSlot, u32 allowedMask, uint32_t *inheritedOtEntry)
{
	int slot = handlerSlot;
	const int *leafIndices = Ovr227_800a239c_GetWaterListLeafWrapperIndices(handlerLabel);

	if (leafIndices != NULL)
	{
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, leafIndices, faceIndex, depth, allowedMask, inheritedOtEntry);
	}

	switch (handlerLabel)
	{
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT0:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT0_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT0_ALIAS_B:
		slot = 0;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT1:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT1_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT1_ALIAS_B:
		slot = 1;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT2:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT2_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT2_ALIAS_B:
		slot = 2;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT3:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT3_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT3_ALIAS_B:
		slot = 3;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT4:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT4_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT4_ALIAS_B:
		slot = 4;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT7:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT7_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT7_ALIAS_B:
		slot = 7;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT9:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT9_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT9_ALIAS_B:
		slot = 9;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT11:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT11_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT11_ALIAS_B:
		slot = 11;
		break;
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT5:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT5_ALIAS_A:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_WRAPPER_SLOT5_ALIAS_B:
		slot = 5;
		break;
	default:
		break;
	}

	// NOTE(aalhendi): Retail 0x800a22a4..0x800a24a4 wrappers are selected by
	// copied setup0 scratch addresses and pass their own t2 direct-mask
	// constants into shared face helper 0x800a25d0.
	switch (slot)
	{
	case 0:
		// 0x800a2344
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridMixedFaceIndices[0], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridMixedFaceIndices[1], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[0], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 1:
		// 0x800a2384
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[1], faceIndex, depth, OVR227_DIRECT_QUAD,
		                                       inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[2], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[3], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 2:
		// 0x800a2404
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[3], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[2], faceIndex, depth,
		                                       OVR227_DIRECT_TRI_PRIMARY, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[0], faceIndex, depth, OVR227_DIRECT_QUAD,
		                                       inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[1], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 3:
		// 0x800a23a4
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[0], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[2], faceIndex, depth, OVR227_DIRECT_QUAD,
		                                       inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[1], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 4:
		// 0x800a242c
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[1], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[1], faceIndex, depth,
		                                       OVR227_DIRECT_TRI_PRIMARY, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[0], faceIndex, depth, OVR227_DIRECT_QUAD,
		                                       inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[2], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 7:
		// 0x800a23c4
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridMixedFaceIndices[2], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridMixedFaceIndices[3], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[3], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 9:
		// 0x800a2454
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[2], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[2], faceIndex, depth,
		                                       OVR227_DIRECT_TRI_SECONDARY, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[1], faceIndex, depth, OVR227_DIRECT_QUAD,
		                                       inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[3], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	case 11:
		// 0x800a247c
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridExtraFaceIndices[0], faceIndex, depth,
		                                       OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[1], faceIndex, depth,
		                                       OVR227_DIRECT_TRI_SECONDARY, inheritedOtEntry))
		{
			return 0;
		}
		if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[2], faceIndex, depth, OVR227_DIRECT_QUAD,
		                                       inheritedOtEntry))
		{
			return 0;
		}
		return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[3], faceIndex, depth,
		                                         OVR227_DIRECT_QUAD, inheritedOtEntry);
	default:
		break;
	}

	// 0x800a24a4
	DrawLevelOvr2P_SetGridFaceSlot(projected, 0);
	if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[0], 0, depth, OVR227_DIRECT_QUAD,
	                                       inheritedOtEntry))
	{
		return 0;
	}
	DrawLevelOvr2P_SetGridFaceSlot(projected, 1);
	if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[1], 1, depth, OVR227_DIRECT_QUAD,
	                                       inheritedOtEntry))
	{
		return 0;
	}
	DrawLevelOvr2P_SetGridFaceSlot(projected, 2);
	if (!Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[2], 2, depth, OVR227_DIRECT_QUAD,
	                                       inheritedOtEntry))
	{
		return 0;
	}
	DrawLevelOvr2P_SetGridFaceSlot(projected, 3);
	return Ovr227_800a26c8_WaterListFaceGate(pb, primMem, block, projected, sDrawLevelOvr2PGridFaceIndices[3], 3, depth, OVR227_DIRECT_QUAD,
	                                         inheritedOtEntry);
}

static int Ovr227_800a28d0_EmitWaterListGT3Raw(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                               const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex, int secondary,
                                               uint32_t *inheritedOtEntry)
{
	int triIndices[3];

	(void)pb;
	(void)block;
	(void)faceIndex;

	if (secondary)
	{
		// NOTE(aalhendi): Retail label 0x800a27d4 does `s3=s4; s4=s6`
		// before falling through to the fixed-code GT3 writer at 0x800a27dc.
		triIndices[0] = indices[1];
		triIndices[1] = indices[3];
		triIndices[2] = indices[2];
	}
	else
	{
		triIndices[0] = indices[0];
		triIndices[1] = indices[1];
		triIndices[2] = indices[2];
	}

	if (inheritedOtEntry == NULL)
	{
		return 1;
	}

	POLY_GT3 *prim = primMem->cursor;
	POLY_GT3 *nextPrim = prim + 1;
	DrawLevelOvr2P_StoreProjectedDirectUvScratch(projected, triIndices, 3);
	u32 uv0 = DrawLevelOvr2P_Scratch()->uv.uv0;
	u32 uv1 = DrawLevelOvr2P_Scratch()->uv.uv1;
	u32 uv2 = DrawLevelOvr2P_Scratch()->uv.uv2;

	DrawLevelOvr2P_WriteProjectedGT3(prim, projected, triIndices, 0x36, uv0, uv1, uv2);
	DrawLevelOvr2P_AddRawPrimToOt(primMem, prim, 9, inheritedOtEntry);
	primMem->cursor = nextPrim;
	return 1;
}

static int Ovr227_800a2944_EmitWaterListGT4Raw(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                               const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                               uint32_t *inheritedOtEntry)
{
	(void)pb;
	(void)block;
	(void)faceIndex;

	if (inheritedOtEntry == NULL)
	{
		return 1;
	}

	POLY_GT4 *prim = primMem->cursor;
	POLY_GT4 *nextPrim = prim + 1;
	DrawLevelOvr2P_StoreProjectedDirectUvScratch(projected, indices, 4);
	u32 uv0 = DrawLevelOvr2P_Scratch()->uv.uv0;
	u32 uv1 = DrawLevelOvr2P_Scratch()->uv.uv1;
	u32 uv2 = DrawLevelOvr2P_Scratch()->uv.uv2;

	DrawLevelOvr2P_WriteProjectedGT4(prim, projected, indices, 0x3e, uv0, uv1, uv2);
	DrawLevelOvr2P_AddRawPrimToOt(primMem, prim, 12, inheritedOtEntry);
	primMem->cursor = nextPrim;
	return 1;
}

static int Ovr227_800a28ac_EmitWaterListDirectTail(struct PushBuffer *pb, struct PrimMem *primMem, const struct QuadBlock *block,
                                                   const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex,
                                                   uint32_t *inheritedOtEntry)
{
	u32 directMask = DrawLevelOvr2P_Scratch()->directMask;
	DrawLevelOvrRetailLabel handlerLabel = DrawLevelOvr2P_GetDirectHandlerAddress(directMask);

	// NOTE(aalhendi): 227/228/229 water-list direct tables use shifted retail
	// labels with the same packet ABI; alias them to the owned native writers.
	switch (handlerLabel)
	{
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_PRIMARY_226:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_PRIMARY_227:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_PRIMARY_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_PRIMARY_229:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_DIRECT_GT3_PRIMARY_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_DIRECT_GT3_PRIMARY_229:
		return Ovr227_800a28d0_EmitWaterListGT3Raw(pb, primMem, block, projected, indices, faceIndex, 0, inheritedOtEntry);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_SECOND_226:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_SECOND_227:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_SECOND_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT3_SECOND_229:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_DIRECT_GT3_SECOND_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_DIRECT_GT3_SECOND_229:
		return Ovr227_800a28d0_EmitWaterListGT3Raw(pb, primMem, block, projected, indices, faceIndex, 1, inheritedOtEntry);
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT4_226:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT4_227:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT4_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_LIST_DIRECT_GT4_229:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_DIRECT_GT4_228:
	case DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_DIRECT_GT4_229:
		return Ovr227_800a2944_EmitWaterListGT4Raw(pb, primMem, block, projected, indices, faceIndex, inheritedOtEntry);
	default:
		return 1;
	}
}

static int Ovr227_800a2758_WaterListNearDispatch(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                                 const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex, int depth,
                                                 DrawLevelOvrRetailLabel handlerLabel, int handlerSlot, u32 allowedMask, uint32_t *inheritedOtEntry)
{
	if (DrawLevelOvr2P_IsDeepestSubdivisionFrame(projected))
	{
		// NOTE(aalhendi): Retail 0x800a265c preserves the current t2 mask,
		// and 0x800a2668 jumps directly to the direct table at 0x800a27b8
		// when the recursion frame reaches scratch 0x324.
		DrawLevelOvr2P_Scratch()->directMask = allowedMask;
		return Ovr227_800a28ac_EmitWaterListDirectTail(pb, primMem, block, projected, indices, faceIndex, inheritedOtEntry);
	}

	struct DrawLevelOvrScratchVertex *sub = DrawLevelOvr2P_GetSubdivisionFrame(depth);
	// NOTE(aalhendi): Retail 0x800a272c..0x800a27a4 advances by 0xb8,
	// builds five 0x800a24e8 midpoint pairs, then jumps through scratch 0x148.
	Ovr227_800a25e0_BuildWaterListSubdivisionFrame(sub, projected, indices);

	return Ovr227_800a239c_DispatchWaterListHelperWrappers(pb, primMem, block, sub, faceIndex, depth + 1, handlerLabel, handlerSlot, allowedMask,
	                                                       inheritedOtEntry);
}

static int Ovr227_800a26c8_WaterListFaceGate(struct PushBuffer *pb, struct PrimMem *primMem, struct QuadBlock *block,
                                             const struct DrawLevelOvrScratchVertex *projected, const int *indices, int faceIndex, int depth, u32 allowedMask,
                                             uint32_t *inheritedOtEntry)
{
	// NOTE(aalhendi): Retail 0x800a25d0..0x800a27b8 owns the shared water-list
	// face gate: packed rectangle reject, color-derived direct mask, top-frame
	// OT inheritance, near-mask selection, and recursive child dispatch.
	if (DrawLevelOvr2P_IsProjectedFaceOffscreen(pb, projected, indices))
	{
		return 1;
	}

	u32 directMask = Ovr227_800a2724_SelectAndStoreWaterDirectMask(projected, indices, allowedMask);
	if (directMask == 0)
	{
		return 1;
	}

	uint32_t *faceOtEntry = Ovr227_800a2788_ResolveWaterListInheritedOtEntry(pb, block, projected, indices, faceIndex, inheritedOtEntry);
	u32 nearMask = DrawLevelOvr2P_GetProjectedWaterNearMask(projected, indices);
	if (nearMask != 0)
	{
		DrawLevelOvrRetailLabel handlerLabel = DrawLevelOvr2P_GetNearSubdivisionHandlerAddress(nearMask, OVR227_CLIP_BYTES_LIST);
		int handlerSlot = DrawLevelOvr2P_GetNearSubdivisionTableSlot(nearMask);

		return Ovr227_800a2758_WaterListNearDispatch(pb, primMem, block, projected, indices, faceIndex, depth, handlerLabel, handlerSlot, directMask,
		                                             faceOtEntry);
	}

	return Ovr227_800a28ac_EmitWaterListDirectTail(pb, primMem, block, projected, indices, faceIndex, faceOtEntry);
}

static void Ovr227_800a1f34_SeedWaterListState(void)
{
	const struct TextureLayout *waterEnvMap = (const struct TextureLayout *)(uintptr_t)DrawLevelOvr2P_Scratch()->waterEnvMapPtr32;

	// NOTE(aalhendi): Retail 0x800a1e30 uses the global 1P retry list, not the
	// current render-list field, before walking the water BSP list.
	if (sDrawLevelOvr2P_ListHandlersSeedRenderedCursor)
	{
		DrawLevelOvr2P_SetRenderedListCursor(DrawLevelOvr2P_GetRenderedOverflowBase());
	}
	CTC2(0, 21);
	CTC2(0, 22);
	CTC2(0, 23);
	DrawLevelOvr2P_Scratch()->uv.uv0 = DrawLevelOvr2P_ReadPackedWord((const u8 *)waterEnvMap + 0);
	DrawLevelOvr2P_Scratch()->uv.uv1 = DrawLevelOvr2P_ReadPackedWord((const u8 *)waterEnvMap + 4);
}

