		DrawLevelOvr2P_SetGridFaceSlot(projected, 2);
		if (!Ovr227_800a2e94_DispatchWaterRenderedHelperWrappers(pb, primMem, block, projected, 2, depth, DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_LEAF_FACE2,
		                                                         -1, OVR227_DIRECT_QUAD, inheritedOtEntry))
		{
			return 0;
		}
		DrawLevelOvr2P_SetGridFaceSlot(projected, 3);
		return Ovr227_800a2e94_DispatchWaterRenderedHelperWrappers(
		    pb, primMem, block, projected, 3, depth, DRAW_LEVEL_OVR_RETAIL_LABEL_WATER_RENDERED_LEAF_FACE3, -1, OVR227_DIRECT_QUAD, inheritedOtEntry);
	default:
